sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var graficoLinhaLiquida = null;
    var dadosOriginaisLiquida = $scope.data.series || [];

    $scope.exibirLinha = dadosOriginaisLiquida.length > 0;

    function arredondarParaCimaMultiplo5Milhoes(num) {
        var base = 5000000; // 5 milhões
        return Math.ceil(num / base) * base;
    }

    function montarGraficoLinhaLiquida(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (graficoLinhaLiquida) {
                graficoLinhaLiquida.destroy();
                graficoLinhaLiquida = null;
            }
            $scope.exibirLinha = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirLinha = true;
        $scope.$applyAsync();

        var listaAnos = listaDados.map(function(item) { return item.ano; });
        var valoresDespesa = listaDados.map(function(item) { return item.valor; });

        var maxValor = Math.max.apply(null, valoresDespesa);
        var maxEixoY = maxValor < 20000000 ? 20000000 : arredondarParaCimaMultiplo5Milhoes(maxValor * 1.25);

        var contexto = document.getElementById('graficoLinhaLiquida').getContext('2d');

        if (graficoLinhaLiquida) {
            graficoLinhaLiquida.destroy();
        }

        graficoLinhaLiquida = new Chart(contexto, {
            type: 'line',
            data: {
                labels: listaAnos,
                datasets: [{
                    label: 'Despesa Líquida com Pessoal',
                    data: valoresDespesa,
                    borderColor: '#6BB7F0', // cor diferente da bruta
                    backgroundColor: '#6BB7F0',
                    borderWidth: 3,
                    tension: 0.2,
                    fill: false,
                    pointRadius: 5,
                    pointBackgroundColor: '#FFF'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        offset: true,
                        title: { display: true, text: 'Ano' }
                    },
                    y: {
                        beginAtZero: true,
                        max: maxEixoY,
                        title: { display: true, text: 'Valores em R$' },
                        ticks: {
                            callback: function(value) {
                                return value.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                },
                plugins: {
                    legend: { position: 'top' },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': ' + context.parsed.y.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                }
            }
        });
    }

    function obterDadosPorAno(ano) {
        if (!ano) {
            return dadosOriginaisLiquida;
        }
        return dadosOriginaisLiquida.filter(function(item) {
            return item.ano == ano;
        });
    }

 /*   $rootScope.$on('anoSelecionado', function(evento, anoSelecionado) {
        var dadosFiltrados = obterDadosPorAno(anoSelecionado);
        montarGraficoLinhaLiquida(dadosFiltrados);
    });*/

    $timeout(function() {
        montarGraficoLinhaLiquida(obterDadosPorAno(null));
    }, 300);
}

sp_widget.css:
h2, h3, div {
  font-family: 'Roboto Flex', sans-serif;
}

sp_widget.script:
(function() {
    var dadosLiquida = [];
    var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
    gr.orderBy('u_ano');
    gr.query();

    while (gr.next()) {
        dadosLiquida.push({
            ano: gr.getValue('u_ano'),
            valor: parseFloat(gr.getValue('u_despesa_liquida_pedidos'))
        });
    }

    data.series = dadosLiquida;
})();
